import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();

        int yigindi = 0;
        int juftlar = 0;
        for (int i = 0; i < n - 1; i++) {
            yigindi += a[i];
            if (a[i] % 2 == 0) juftlar++;
        }

        System.out.println(yigindi);
        System.out.println(juftlar);
    }
}

